# Check which conv2 channels feed into filter 10 (conv3 filter 10)
conv3_w = W['conv3.weight']
f10 = conv3_w[10]  # (32, 3, 3)

print("Filter 10: norm per input channel (conv2 output channel)")
for c in range(32):
    norm = f10[c].norm().item()
    if norm > 0.5:
        print(f"  Channel {c}: norm={norm:.4f}")

# Also check filter 9, 45
